package bench.common.model;

import java.math.BigDecimal;
import java.time.Instant;
import java.time.LocalDate;
import java.util.List;
import java.util.UUID;

/**
 * Framework-neutral scenario inputs and small result holders.
 */
public final class Inputs {

    private Inputs() {
    }

    /**
     * A book to insert; the id is generated by the database.
     */
    public record NewBook(long authorId, String title, String isbn, int pages, BigDecimal price, LocalDate publishedOn) {
    }

    /**
     * An order with its lines to insert in one cascading save.
     */
    public record NewOrder(UUID reference, String customer, Instant createdAt, List<NewOrderLine> lines) {
    }

    /**
     * A line of a {@link NewOrder}.
     */
    public record NewOrderLine(int lineNo, String product, int quantity, BigDecimal unitPrice) {
    }

    /**
     * Filter for the dynamic criteria scenario. A {@code null} field means "no predicate".
     */
    public record BookFilter(Long authorId, Integer minPages, Integer maxPages, BigDecimal maxPrice) {
    }

    /**
     * One element of a dynamic sort. {@code property} is the entity attribute name.
     */
    public record SortOrder(String property, boolean ascending) {
    }

    /**
     * Content and total count of an offset page.
     */
    public record BookPage(List<? extends BookView> content, long totalSize) {
    }
}
